    82  /// <summary>
    83  /// Provided with a block pointer with populated type and length, this will actually parse out the body and options
    84  /// </summary>
    85  /// <param name="current">Block pointer with type and length filled out</param>
    86  /// <param name="local_data">Pointer to data which constitutes block body</param>
    87  /// <param name="block_start">Pointer to the start of the block data</param>
    88  void parse_by_block_type(struct _light_pcapng *current, const uint32_t *local_data, const uint32_t *block_start)
    89  {
    90     switch (current->block_type)
    91     {
    92        case LIGHT_SECTION_HEADER_BLOCK:
    93        {
    94           DPRINT_HERE(LIGHT_SECTION_HEADER_BLOCK);
    95           struct _light_section_header *shb = calloc(1, sizeof(struct _light_section_header));
    96           struct _light_option *opt = NULL;
    97           uint32_t version;
    98           int32_t local_offset;
    99
   100           shb->byteorder_magic = *local_data++;
   101           // TODO check byte order.
   102           version = *local_data++;
   103           shb->major_version = version & 0xFFFF;
   104           shb->minor_version = (version >> 16) & 0xFFFF;
   105           shb->section_length = *((uint64_t*)local_data);
   106           local_data += 2;
   107
   108           current->block_body = (uint32_t*)shb;
   109           local_offset = (size_t)local_data - (size_t)block_start;
   110           opt = __parse_options((uint32_t **)&local_data, current->block_total_length - local_offset - sizeof(current->block_total_length));
   111           current->options = opt;
   112        }
   113        break;
   114
   115        case LIGHT_INTERFACE_BLOCK:
   116        {
   117           DPRINT_HERE(LIGHT_INTERFACE_BLOCK);
   118           struct _light_interface_description_block *idb = calloc(1, sizeof(struct _light_interface_description_block));
   119           struct _light_option *opt = NULL;
   120           uint32_t link_reserved = *local_data++;
   121           int32_t local_offset;
   122
   123           idb->link_type = link_reserved & 0xFFFF;
   124           idb->reserved = (link_reserved >> 16) & 0xFFFF;
   125           idb->snapshot_length = *local_data++;
   126           current->block_body = (uint32_t*)idb;
   127           local_offset = (size_t)local_data - (size_t)block_start;
   128           opt = __parse_options((uint32_t **)&local_data, current->block_total_length - local_offset - sizeof(current->block_total_length));
   129           current->options = opt;
   130        }
   131        break;
   132
   133        case LIGHT_ENHANCED_PACKET_BLOCK:
   134        {
   135           DPRINT_HERE(LIGHT_ENHANCED_PACKET_BLOCK);
   136           struct _light_enhanced_packet_block *epb = NULL;
   137           struct _light_option *opt = NULL;
   138           uint32_t interface_id = *local_data++;
   139           uint32_t timestamp_high = *local_data++;
   140           uint32_t timestamp_low = *local_data++;
   141           uint32_t captured_packet_length = *local_data++;
   142           uint32_t original_packet_length = *local_data++;
   143           int32_t local_offset;
   144           uint32_t actual_len = 0;
   145
   146           PADD32(captured_packet_length, &actual_len);
   147
   148           epb = calloc(1, sizeof(struct _light_enhanced_packet_block) + actual_len);
   149           epb->interface_id = interface_id;
   150           epb->timestamp_high = timestamp_high;
   151           epb->timestamp_low = timestamp_low;
   152           epb->capture_packet_length = captured_packet_length;
   153           epb->original_capture_length = original_packet_length;
   154
   155           memcpy(epb->packet_data, local_data, captured_packet_length); // Maybe actual_len?
   156           local_data += actual_len / sizeof(uint32_t);
   157           current->block_body = (uint32_t*)epb;
   158           local_offset = (size_t)local_data - (size_t)block_start;
   159           opt = __parse_options((uint32_t **)&local_data, current->block_total_length - local_offset - sizeof(current->block_total_length));
   160           current->options = opt;
   161        }
   162        break;
   163
   164        case LIGHT_SIMPLE_PACKET_BLOCK:
   165        {
   166           DPRINT_HERE(LIGHT_SIMPLE_PACKET_BLOCK);
   167           struct _light_simple_packet_block *spb = NULL;
   168           uint32_t original_packet_length = *local_data++;
   169           uint32_t actual_len = current->block_total_length - 2 * sizeof(current->block_total_length) - sizeof(current->block_type) - sizeof(original_packet_length);
   170
   171           spb = calloc(1, sizeof(struct _light_enhanced_packet_block) + actual_len);
   172           spb->original_packet_length = original_packet_length;
   173
   174           memcpy(spb->packet_data, local_data, actual_len);
   175           local_data += actual_len / sizeof(uint32_t);
   176           current->block_body = (uint32_t*)spb;
   177           current->options = NULL; // No options defined by the standard for this block type.
   178        }
   179        break;
   180
   181        case LIGHT_CUSTOM_DATA_BLOCK:
   182        {
   183           DPRINT_HERE(LIGHT_CUSTOM_DATA_BLOCK);
   184           struct _light_custom_nonstandard_block *cnb = NULL;
   185           struct _light_option *opt = NULL;
   186           uint32_t len = *local_data++;
   187           uint32_t reserved0 = *local_data++;
   188           uint32_t reserved1 = *local_data++;
   189           int32_t local_offset;
   190           uint32_t actual_len = 0;
   191
   192           PADD32(len, &actual_len);
   193           cnb = calloc(1, sizeof(struct _light_custom_nonstandard_block) + actual_len);
   194           cnb->data_length = len;
   195           cnb->reserved0 = reserved0;
   196           cnb->reserved1 = reserved1;
   197
   198           memcpy(cnb->packet_data, local_data, len); // Maybe actual_len?
   199           local_data += actual_len / sizeof(uint32_t);
   200           current->block_body = (uint32_t*)cnb;
   201           local_offset = (size_t)local_data - (size_t)block_start;
   202           opt = __parse_options((uint32_t **)&local_data, current->block_total_length - local_offset - sizeof(current->block_total_length));
   203           current->options = opt;
   204        }
   205        break;
   206
   207        default: // Could not find registered block type. Copying data as RAW.
   208        {
   209           DPRINT_HERE(default);
   210           uint32_t raw_size = current->block_total_length - 2 * sizeof(current->block_total_length) - sizeof(current->block_type);
   211           if (raw_size > 0)
   212           {
   213              current->block_body = calloc(raw_size, 1);
   214              memcpy(current->block_body, local_data, raw_size);
   215              local_data += raw_size / (sizeof(*local_data));
   216           }
   217           else
   218           {
   219              current->block_body = NULL;
   220           }
   221        }
   222        break;
   223     }
   224  }
