    33  struct _light_option *__copy_option(const struct _light_option *option)
    34  {
    35          if (option == NULL) {
    36                  return NULL;
    37          }
    38
    39          size_t current_size = 0;
    40          struct _light_option *copy = calloc(1, sizeof(struct _light_option));
    41
    42          PADD32(option->option_length, &current_size);
    43
    44          copy->custom_option_code = option->custom_option_code;
    45          copy->option_length = option->option_length;
    46          copy->data = calloc(1, current_size);
    47          memcpy(copy->data, option->data, option->option_length);
    48
    49          copy->next_option = __copy_option(option->next_option);
    50
    51          return copy;
    52  }
