    54  struct _light_pcapng *__copy_block(const struct _light_pcapng *pcapng, const light_boolean recursive)
    55  {
    56          if (pcapng == NULL) {
    57                  return NULL;
    58          }
    59
    60          size_t body_length = pcapng->block_total_length - 2 * sizeof(pcapng->block_total_length) - sizeof(pcapng->block_type);
    61          struct _light_pcapng *pcopy = calloc(1, sizeof(struct _light_pcapng));
    62          size_t option_length = 0;
    63
    64          pcopy->block_type = pcapng->block_type;
    65          pcopy->block_total_length = pcapng->block_total_length;
    66          pcopy->options = __copy_option(pcapng->options);
    67          option_length = __get_option_total_size(pcopy->options);
    68          body_length -= option_length;
    69
    70          pcopy->block_body = calloc(body_length, 1);
    71          memcpy(pcopy->block_body, pcapng->block_body, body_length);
    72
    73          if (recursive == LIGHT_TRUE) {
    74                  pcopy->next_block = __copy_block(pcapng->next_block, recursive);
    75          }
    76          else {
    77                  pcopy->next_block = NULL;
    78          }
    79
    80          return pcopy;
    81  }
