    83  size_t __get_option_total_size(const struct _light_option *option)
    84  {
    85          size_t size = 0;
    86
    87          while (option != NULL) {
    88                  uint16_t actual_length;
    89                  PADD32(option->option_length, &actual_length);
    90                  size += 4 + actual_length;
    91                  option = option->next_option;
    92          }
    93
    94          return size;
    95  }
