    97  uint32_t *__get_option_size(const struct _light_option *option, size_t *size)
    98  {
    99          if (option == NULL) {
   100                  *size = 0;
   101                  return NULL;
   102          }
   103
   104          size_t next_size;
   105          uint32_t *next_option = __get_option_size(option->next_option, &next_size);
   106          uint32_t *current_mem;
   107          size_t current_size = 0;
   108
   109          PADD32(option->option_length, &current_size);
   110
   111          current_mem = calloc(sizeof(uint32_t) + current_size + next_size, 1);
   112          current_mem[0] = option->custom_option_code | (option->option_length << 16);
   113          memcpy(&current_mem[1], option->data, current_size);
   114          memcpy(&current_mem[1 + current_size / 4], next_option, next_size);
   115
   116          current_size += sizeof(option->custom_option_code) + sizeof(option->option_length) + next_size;
   117          *size = current_size;
   118
   119          free(next_option);
   120
   121          return current_mem;
   122  }
