   124  light_boolean __is_section_header(const struct _light_pcapng * section)
   125  {
   126          if (section != NULL) {
   127                  if (section->block_type != LIGHT_SECTION_HEADER_BLOCK) {
   128                          return LIGHT_FALSE;
   129                  }
   130                  else {
   131                          return LIGHT_TRUE;
   132                  }
   133          }
   134
   135          return LIGHT_FALSE;
   136  }
