   138  int __validate_section(struct _light_pcapng *section)
   139  {
   140          if (__is_section_header(section) != LIGHT_TRUE) {
   141                  return LIGHT_INVALID_SECTION;
   142          }
   143
   144          struct _light_section_header *shb = (struct _light_section_header *)section->block_body;
   145          uint64_t size = section->block_total_length;
   146          struct _light_pcapng *next_block = section->next_block;
   147
   148          while (next_block != NULL) {
   149                  if (__is_section_header(next_block) == LIGHT_TRUE) {
   150                          shb->section_length = size;
   151                          return __validate_section(next_block);
   152                  }
   153                  else {
   154                          size += next_block->block_total_length;
   155                          next_block = next_block->next_block;
   156                  }
   157          }
   158
   159          shb->section_length = size;
   160          return LIGHT_SUCCESS;
   161  }
